+            'syntax',
+            $file.':'.($phpVersion ?? PHP_VERSION_ID),
+            hash('sha256', $contents),
+            self::class,
+            $parse,
+        );
+    }
+
+    private static function parse(string $contents, Parser $parser): self
+    {
+        $errors = new Collecting();
+        $parsed = $parser->parse($contents, $errors);
