    public static function fingerprint(array $files, array $options): string
    {
        $directory = getcwd();
        $hash = hash_init('sha256');
        hash_update($hash, serialize([$directory, PHP_VERSION_ID, get_loaded_extensions(), $files, $options]));
        $paths = array_fill_keys($files, true);
